(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let tab='科研信息',scope='';
  const status=s=>`<span class="so-status ${s==='已完成'?'done':s==='运行中'?'running':'pending'}">${esc(s)}</span>`;
  const link=(label,route)=>`<button class="so-link" data-route="${route}">${label} →</button>`;
  const profile=c=>({owner:'林夏',project:c.name==='页岩气储层评价'?'非常规油气前沿研究':c.name==='高性能合成橡胶'?'高性能材料研发':'低碳与新材料研究',intro:`围绕${c.name}开展证据研读、数据分析与计算实验，保留研究过程并沉淀经确认的科研资产。`,members:['林夏','陈明','王博士','赵岩'],...c});
  const RU=()=>window.AI4SResourceUsage;
  const typeNames=()=>window.AI4SExecutionCenter?.types?.()||{compute:'科学计算',training:'模型训练',inference:'模型推理',experiment:'实验验证',analysis:'数据分析'};
  const level=p=>p>=85?'danger':p>=70?'warn':'ok';
  function meter(label,used,total,unit,d=0){const R=RU(),p=Math.min(100,used/total*100);return `<div class="ru-meter ${level(p)}"><div class="ru-meter-top"><span>${label}</span><b>${p.toFixed(0)}%</b></div><strong>${R.fmt(used,d)}<small> / ${R.fmt(total,d)} ${unit}</small></strong><i><em style="width:${p.toFixed(1)}%"></em></i><small>剩余 ${R.fmt(total-used,d)} ${unit}${p>=85?' · 接近上限':''}</small></div>`;}
  function bars(data,key,color,unit,mini=false){const max=Math.max(...data.map(d=>d[key]),1),w=560,h=150,bw=w/data.length;return `<svg class="ru-chart" viewBox="0 0 ${w} ${mini?h:h+26}" ${mini?'preserveAspectRatio="none"':''} role="img" aria-label="近 ${data.length} 天${unit}趋势"><path d="M0 ${h}H${w}" stroke="#dbe6f3"/>${data.map((d,i)=>{const bh=Math.max(2,d[key]/max*(h-18));return `<rect x="${i*bw+bw*0.2}" y="${h-bh}" width="${bw*0.6}" height="${bh}" rx="2" fill="${color}"><title>${d.label} · ${d[key]} ${unit}</title></rect>${mini||i%2===data.length%2?'':`<text x="${i*bw+bw/2}" y="${h+17}" text-anchor="middle" font-size="11" fill="#8aa0bb">${d.label}</text>`}`;}).join('')}</svg>`;}
  function usageSummary(c){const R=RU();if(!R)return '';const p=R.pool(c.name),t=R.trend(c.name,7),week=t.reduce((a,d)=>a+d.gpu,0),running=(window.AI4SExecutionCenter?.records(c.name)||[]).filter(r=>r.status==='运行中').length;return `<section class="so-card ru-summary"><div class="so-card-head"><h3>资源用量 <small>本月 · 资源池计量（演示）</small></h3><button class="so-link" data-so-tab="资源用量">查看明细 →</button></div><div class="ru-summary-grid">${meter('GPU 算力',p.gpu[0],p.gpu[1],'卡时')}${meter('CPU 算力',p.cpu[0],p.cpu[1],'核时')}${meter('存储',p.storage[0],p.storage[1],'TB',1)}<div class="ru-mini"><span>近 7 天 GPU 消耗</span><strong>${R.fmt(week)}<small> 卡时</small></strong>${bars(t,'gpu','#4d8ff0','卡时',true)}<small>${running} 个执行任务正在占用资源</small></div></div><p class="ru-pool">挂载资源池：${esc(p.pool)}</p></section>`;}
  function usageDetail(c){const R=RU();if(!R)return '<section class="so-card"><p>资源计量组件未加载。</p></section>';const p=R.pool(c.name),t=R.trend(c.name,14),names=typeNames(),mixG=Object.values(p.mix).reduce((a,v)=>a+v[0],0),mixC=Object.values(p.mix).reduce((a,v)=>a+v[1],0),maxG=Math.max(...Object.values(p.mix).map(v=>v[0])),maxC=Math.max(...Object.values(p.mix).map(v=>v[1]));
    const typeRows=Object.entries(p.mix).map(([k,[g,cp]])=>{const gv=p.gpu[0]*g/mixG,cv=p.cpu[0]*cp/mixC;return `<tr><td>${esc(names[k]||k)}</td><td><div class="ru-bar"><i style="width:${g/maxG*100}%"></i><span>${R.fmt(gv)} 卡时</span></div></td><td><div class="ru-bar cpu"><i style="width:${cp/maxC*100}%"></i><span>${R.fmt(cv)} 核时</span></div></td><td>${(g/mixG*100).toFixed(0)}% / ${(cp/mixC*100).toFixed(0)}%</td></tr>`;}).join('');
    const store=[['数据集',0.42],['模型与权重',0.26],['执行产物',0.19],['沙盒文件',0.13]];
    const runs=(window.AI4SExecutionCenter?.records(c.name)||[]).map(r=>({r,u:R.usage(r)})).filter(x=>x.u.started).sort((a,b)=>(b.u.gpuHours*16+b.u.cpuHours)-(a.u.gpuHours*16+a.u.cpuHours)).slice(0,6);
    return `<div class="ru-summary-grid ru-detail-meters">${meter('GPU 算力',p.gpu[0],p.gpu[1],'卡时')}${meter('CPU 算力',p.cpu[0],p.cpu[1],'核时')}${meter('存储',p.storage[0],p.storage[1],'TB',1)}</div><p class="ru-pool">挂载资源池：${esc(p.pool)} · 上限为建空间时分配的配额 · 本月数据为演示计量</p>
    <div class="so-two ru-two"><section class="so-card"><div class="so-card-head"><h3>近 14 天 GPU 消耗</h3><span>卡时 / 天</span></div>${bars(t,'gpu','#4d8ff0','卡时')}</section><section class="so-card"><div class="so-card-head"><h3>近 14 天 CPU 消耗</h3><span>核时 / 天</span></div>${bars(t,'cpu','#33a99a','核时')}</section></div>
    <div class="ru-split"><section class="so-card"><div class="so-card-head"><h3>按执行类型分布 <small>本月</small></h3>${link('进入作业监控','space-compute')}</div><table class="so-table ru-type-table"><thead><tr><th>执行类型</th><th>GPU</th><th>CPU</th><th>占比 GPU / CPU</th></tr></thead><tbody>${typeRows}</tbody></table></section><section class="so-card"><div class="so-card-head"><h3>存储构成</h3><span>${R.fmt(p.storage[0],1)} TB 已用</span></div><div class="ru-store">${store.map(([n,v])=>`<div><span>${n}</span><i><em style="width:${v*100}%"></em></i><b>${R.fmt(p.storage[0]*v,2)} TB</b></div>`).join('')}</div></section></div>
    <section class="so-card"><div class="so-card-head"><h3>资源消耗较高的执行任务</h3><span>点击查看单任务资源消耗与日志</span></div><table class="so-table"><thead><tr><th>执行任务</th><th>类型</th><th>状态</th><th>GPU</th><th>CPU</th><th>运行时长</th><th></th></tr></thead><tbody>${runs.map(({r,u})=>`<tr><td><button class="so-link" data-so-exec="${esc(r.id)}">${esc(r.name)}</button><small>${esc(r.researchTitle||'')}</small></td><td>${esc(names[r.category]||r.category)}</td><td>${status(r.status)}</td><td>${esc(u.text.gpu)}</td><td>${esc(u.text.cpu)}</td><td>${esc(u.text.wall)}</td><td><button class="so-link" data-so-exec="${esc(r.id)}">查看 →</button></td></tr>`).join('')||'<tr><td colspan="7">暂无已开始计量的执行任务。</td></tr>'}</tbody></table></section>
    <div class="ru-admin"><span>按成员统计、细粒度查询、扩容等运维操作由管理员在资源看板中处理。</span><button disabled title="规划中">管理员资源看板（规划中）</button></div>`;}
  function markup(c){if(scope!==c.name){scope=c.name;tab='科研信息';}c=profile(c);let data={};try{data=JSON.parse(localStorage.getItem('ai4s-research-workflow-v1')||'{}')[c.name]||{};}catch{} const assets=data.reusable||[],files=c.files||[],unique=[...new Map(files.map(f=>[f.id,f])).values()],tasks=c.tasks||[],runs=window.AI4SExecutionCenter?.records(c.name)||[],completed=tasks.filter(t=>t.status==='已完成').length;
    const metrics=[['科研任务',tasks.length,'space-tasks'],['作业',runs.length,'space-compute'],['空间文件',unique.length,'space-materials'],['科研资产',assets.length,'space-materials']];
    const table=()=>`<table class="so-table"><thead><tr><th>任务名称</th><th>研究方式</th><th>状态</th><th>会话</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="so-link" data-so-task="${esc(t.id)}">${esc(t.name)}</button><small>${esc(t.id)}</small></td><td>${esc(t.mode)}</td><td>${status(t.status)}</td><td>${t.sessions} 次</td><td><button class="so-link" data-so-task="${esc(t.id)}">打开任务 →</button></td></tr>`).join('')||'<tr><td colspan="5">尚无科研任务，前往科研任务创建。</td></tr>'}</tbody></table>`;
    let content='';
    if(tab==='科研信息')content=`<div class="so-info-grid"><div class="so-info-main"><section class="so-card"><h3>课题简介</h3><p>${esc(c.intro)}</p><div class="so-question"><span>课题关键问题</span><strong>${esc(c.problem.question)}</strong>${link('查看关键问题','space-questions')}</div></section><div class="so-two"><section class="so-card"><h3>研究目标</h3><ul><li>${esc(c.problem.criterion)}</li><li>明确证据适用范围与关键不确定性</li><li>形成可追溯、可复核的研究成果</li></ul></section><section class="so-card"><h3>任务要求</h3><ul><li>核对输入数据、引用来源与版本</li><li>通过计算或实验检验研究假设</li><li>关键判断由科研人员复核确认</li></ul></section></div></div><section class="so-card so-basic"><h3>基本信息 <small>示例信息</small></h3><dl><dt>所属方向</dt><dd>${esc(c.problem.domain)}</dd><dt>课题负责人</dt><dd>${esc(c.owner)}</dd><dt>课题成员</dt><dd>${c.members.length} 人</dd><dt>所属项目</dt><dd>${esc(c.project)}</dd><dt>课题周期</dt><dd>2026—2027（示例）</dd><dt>当前阶段</dt><dd>${esc(c.problem.stage)}</dd><dt>空间权限</dt><dd>课题成员可见（示例）</dd></dl></section></div><section class="so-card"><div class="so-card-head"><h3>当前研究进展</h3><span>研究阶段示意 · 以任务与验证记录为准</span></div><div class="so-stages">${['问题界定','证据与数据','计算分析','实验验证','成果确认'].map((s,i)=>{const active=c.problem.stage.includes('实验')?3:c.problem.stage.includes('参数')?2:1;return `<div class="${i===active?'current':i<active?'passed':''}"><i>${i<active?'✓':i+1}</i><strong>${s}</strong><small>${i===active?'当前关注':i<active?'已开展':'后续环节'}</small></div>`;}).join('')}</div><div class="so-current"><span>当前判断</span><p>${esc(c.problem.answer)}</p>${link('继续验证','space-tasks')}</div></section><section class="so-card"><div class="so-card-head"><h3>当前科研任务 <small>${completed} / ${tasks.length} 已完成</small></h3>${link('全部任务','space-tasks')}</div>${table()}</section>`;
    if(tab==='课题成员')content=`<section class="so-card"><div class="so-card-head"><h3>课题成员 <small>示例成员</small></h3><span>任务协同与评审在科研任务中管理</span></div><table class="so-table"><thead><tr><th>成员</th><th>角色</th><th>研究分工</th><th>权限</th></tr></thead><tbody>${c.members.map((m,i)=>`<tr><td><span class="so-avatar">${m[0]}</span>${m}</td><td>${i===0?'课题负责人':'课题成员'}</td><td>${['研究统筹与结果复核','数据分析与模型验证','实验设计与测试','领域证据研判'][i]}</td><td>课题内协作</td></tr>`).join('')}</tbody></table><p class="so-note">成员信息为原型示例；真实组织成员和权限尚未接入。</p></section>`;
    if(tab==='科研任务')content=`<section class="so-card"><div class="so-card-head"><h3>空间科研任务</h3>${link('进入科研任务','space-tasks')}</div>${table()}</section>`;
    if(tab==='科研产出')content=`<section class="so-card"><div class="so-card-head"><h3>空间产出</h3>${link('管理空间资产','space-materials')}</div><p class="so-note">空间文件保留输入、过程与输出；发布后形成正式科研资产，上架后可在广场共享。</p><table class="so-table"><thead><tr><th>名称</th><th>类型</th><th>来源</th><th>状态</th><th></th></tr></thead><tbody>${assets.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.type)}</td><td>科研资产</td><td>${status(a.status||'已发布')}</td><td>${link('查看资产','space-materials')}</td></tr>`).join('')}${unique.filter(f=>f.kind==='执行输出').map(f=>`<tr><td>${esc(f.name)}</td><td>${esc(f.type||'文件')}</td><td>${esc(f.session)}</td><td>${status('待复核')}</td><td>${link('查看文件','space-materials')}</td></tr>`).join('')||(!assets.length?'<tr><td colspan="5">尚无执行输出；空间文件可在空间资产中查看。</td></tr>':'')}</tbody></table></section>`;
    if(tab==='资源用量')content=usageDetail(c);
    return `<div class="page so-page"><header class="so-header"><div><div class="so-kicker">当前课题空间</div><h1>${esc(c.name)}</h1><p>${esc(c.problem.domain)} <span>·</span> ${esc(c.problem.stage)}</p></div><div>${link('关键问题','space-questions')}${link('科研任务','space-tasks')}</div></header><div class="so-meta"><span>林夏</span><span>${esc(c.project)} <em>示例</em></span><span>${c.members.length} 位成员 <em>示例</em></span></div><div class="so-metrics">${metrics.map(([l,n,r])=>`<button data-route="${r}"><strong>${n}</strong><span>${l}</span><i>↗</i></button>`).join('')}</div>${tab!=='资源用量'?usageSummary(c):''}<nav class="so-tabs" aria-label="空间概览内容">${['科研信息','课题成员','科研任务','科研产出','资源用量'].map(t=>`<button data-so-tab="${t}" class="${tab===t?'active':''}" aria-selected="${tab===t}">${t}</button>`).join('')}</nav>${content}</div>`;
  }
  function bind(c){document.querySelectorAll('[data-so-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.soTab;c.render();});document.querySelectorAll('[data-so-task]').forEach(b=>b.onclick=()=>c.openTask(b.dataset.soTask));document.querySelectorAll('[data-so-exec]').forEach(b=>b.onclick=()=>c.openExec?.(b.dataset.soExec));}
  window.AI4SSpaceOverview={markup,bind};
})();
